define(["core/ajax","core/templates","core/notification"],function(Ajax,Templates,Notification){"use strict";return{init:function(config){var root=document.getElementById(config.rootid);if(!root){return}var request=Ajax.call([{methodname:"block_personalprogress_get_dashboard",args:{courseid:config.courseid,blockinstanceid:config.blockinstanceid}}])[0];request.then(function(data){return Templates.render("block_personalprogress/dashboard",data)}).then(function(html){root.innerHTML=html;root.setAttribute("aria-busy","false")}).catch(function(error){root.textContent=root.dataset.errorLabel||"";root.setAttribute("aria-busy","false");Notification.exception(error)})}}});
